using Dapper; using InovaGed.Application.Common.Database; using InovaGed.Application.Continuity; using Microsoft.Extensions.Options;
namespace InovaGed.Infrastructure.Continuity;
public sealed class BackupRetentionService(IDbConnectionFactory db,IOptions<BackupOptions> options):IBackupRetentionService { public async Task<int> MarkExpiredAsync(Guid? tenantId,string requestedBy,CancellationToken ct){await using var c=await db.OpenAsync(ct);const string sql="""with candidates as (select s.id from ged.backup_set s left join ged.backup_policy p on p.id=s.policy_id where (@tenantId is null or s.tenant_id=@tenantId) and s.status='COMPLETED' and s.finished_at_utc < now()-(coalesce(p.retention_days,@defaultDays)||' days')::interval and s.id<>(select id from ged.backup_set x where x.tenant_id is not distinct from s.tenant_id and x.integrity_status='VALID' order by x.finished_at_utc desc limit 1) and not exists(select 1 from ged.data_retention_hold h where h.tenant_id is not distinct from s.tenant_id and h.status='ACTIVE') and not exists(select 1 from ged.backup_verification v where v.backup_set_id=s.id and v.status='RUNNING')) update ged.backup_set s set status='RETENTION_PENDING' from candidates c where s.id=c.id""";return await c.ExecuteAsync(new CommandDefinition(sql,new{tenantId,defaultDays=options.Value.DefaultRetentionDays,requestedBy,deletionEnabled=options.Value.RetentionDeletionEnabled},cancellationToken:ct));} }
